        updateHeight(node);
        return rebalance(node);
    }

    private static <T> void collectPreOrder(Node<T> node, List<T> result) {
        if (node != null) {
            result.add(node.key);
            collectPreOrder(node.left, result);
            collectPreOrder(node.right, result);
        }
    }

    private static <T> void collectInOrder(Node<T> node, List<T> result) {
        if (node != null) {
            collectInOrder(node.left, result);
            result.add(node.key);
            collectInOrder(node.right, result);
        }
    }

    public static void main(String[] args) {
